CREATE TEMPORARY VIEW dwd_raw_data_${grass_region_without_quote} AS
SELECT
    user_id
    ,page_type
    ,page_section
    ,device_id
    ,search_session_id
    ,request_id
    ,keyword
    ,TRANSFORM(search_filter_string, x -> FROM_JSON(x, 'STRUCT<filter_group_name:STRING,filter_name:STRING,filter_option:STRING,is_shortcut:BOOLEAN,address_id:BIGINT>')) AS search_filter
    ,IF(target_type = 'shop', 'results-shop', target_type) AS card_type
    ,COALESCE(CAST(layout_type AS STRING), '2') AS layout_type
    ,IF(target_type = 'shop', shop_layout_item_list, ARRAY(item_id)) AS item_id
    ,shop_id
    ,order_id
    ,operation_cnt
    ,operation
    ,place_order_gmv AS gmv
    ,local_hour
FROM
    srdi_mart.dwd_sr_data_warehouse_search
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND user_id > 0
    AND page_type IN ('global_search','search_in_pdp','search_prefill')
    AND (
        (page_section IS NULL AND target_type IN ('item', 'video', 'livestream'))
        OR (page_section[0] = 'results' AND target_type = 'shop')
        OR ( -- For no result count metric
            operation = 'impression' AND (
                (page_section IS NULL AND target_type IN ('no_recall_general', 'no_recall_with_filter'))
                OR (page_section[0] = 'no_recall_with_filter' AND target_type = 'try_diff_address')
            )
        )
    )
    AND operation IN ('click', 'impression', 'order')
UNION ALL
