    ,If(source1_target_type = 'shop', 'results-shop', source1_target_type) AS card_type
    ,COALESCE(CAST(source1_layout_type AS STRING), '2') AS layout_type
    ,IF(source1_target_type = 'shop', source1_shop_layout_item_list, ARRAY(item_id)) AS item_id
    ,shop_id
    ,order_id
    ,operation_cnt
    ,operation
    ,place_order_gmv AS gmv
    ,local_hour
FROM
    srdi_mart.dwd_sr_data_warehouse_search
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND user_id > 0
    AND source1_page_type IN ('global_search','search_in_pdp','search_prefill')
    AND (
        (source1_page_section IS NULL AND source1_target_type IN ('item', 'video', 'livestream')
        OR (source1_page_section[0] = 'results' AND source1_target_type = 'shop'))
    )
    AND operation = 'order'
UNION ALL
