    ,device_id
    ,source2_search_session_id AS search_session_id
    ,source2_request_id AS request_id
    ,source2_keyword AS keyword
    ,TRANSFORM(source2_search_filter_string, x -> FROM_JSON(x, 'STRUCT<filter_group_name:STRING,filter_name:STRING,filter_option:STRING,is_shortcut:BOOLEAN,address_id:BIGINT>')) AS search_filter
    ,If(source2_target_type = 'shop', 'results-shop', source2_target_type) AS card_type
    ,COALESCE(CAST(source2_layout_type AS STRING), '2') AS layout_type
    ,IF(source2_target_type = 'shop', source2_shop_layout_item_list, ARRAY(item_id)) AS item_id
    ,shop_id
