CREATE TEMPORARY VIEW dwd_raw_data_filter_search_filter_${grass_region_without_quote} AS
SELECT
    user_id
    ,device_id
    ,search_session_id
    ,request_id
    ,keyword
    ,FILTER(search_filter,  x -> LOWER(x.filter_name) IN ('instant_delivery', 'fast_delivery')) AS search_filter
    ,card_type
    ,layout_type
    ,item_id
    ,shop_id
    ,order_id
    ,operation_cnt
    ,operation
    ,gmv
    ,local_hour
FROM
    dwd_raw_data_${grass_region_without_quote}
WHERE
    EXISTS(search_filter, x -> LOWER(x.filter_name) IN ('instant_delivery', 'fast_delivery'));

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwd_filtered_data_explode_address_id_${grass_region_without_quote} AS
SELECT
    user_id
    ,device_id
    ,search_session_id
    ,request_id
    ,keyword
    ,search_filter_detail.address_id AS address_id
    ,TRANSFORM(search_filter, x -> STRUCT(x.filter_group_name AS filter_group_name
        ,x.filter_name AS filter_name, x.filter_option AS filter_option, x.is_shortcut AS is_shortcut_filter)) AS search_filter
    ,card_type
    ,layout_type
    ,item_id
    ,shop_id
    ,order_id
    ,local_hour
    ,operation_cnt
    ,operation
    ,gmv
FROM
    dwd_raw_data_filter_search_filter_${grass_region_without_quote}
LATERAL VIEW
    EXPLODE(search_filter) AS search_filter_detail;

