CREATE TEMPORARY VIEW dwm_avg_edt_link_${grass_region_without_quote} AS
SELECT
    user_id
    ,device_id
    ,search_session_id
    ,request_id
    ,keyword
    ,address_id
    ,search_filter
    ,card_type
    ,layout_type
    ,item_id
    ,shop_id
    ,local_hour
    ,order_id
FROM
    dwd_filtered_data_explode_address_id_${grass_region_without_quote}
WHERE
    operation = 'order'
    AND order_id IS NOT NULL
