INSERT OVERWRITE ${schema}.dws_sr_data_warehouse_search_instant_filter_metrics_1d
PARTITION (
    grass_region = ${grass_region}
    ,local_date = ${local_date}
)
SELECT
    a.user_id AS user_id
    ,a.device_id AS device_id
    ,a.address_state AS address_state
    ,a.search_session_id AS search_session_id
    ,a.request_id AS request_id
    ,a.keyword AS keyword
    ,a.address_id AS address_id
    ,a.search_filter AS search_filter
    ,a.card_type AS card_type
    ,a.layout_type AS layout_type
    ,a.item_id AS item_id
    ,a.shop_id AS shop_id
    ,imp_cnt
    ,click_cnt
    ,order_cnt
    ,gmv
    ,no_results_cnt
    ,avg_edt
    ,ads_rev
    ,a.local_hour AS local_hour
FROM
    dws_main_metrics_${grass_region_without_quote} a
LEFT JOIN
    dws_ads_revenue_${grass_region_without_quote} b
ON
    a.user_id <=> b.user_id
    AND a.device_id <=> b.device_id
    AND a.address_state <=> b.address_state
    AND a.search_session_id <=> b.search_session_id
    AND a.request_id <=> b.request_id
    AND a.keyword <=> b.keyword
    AND a.address_id <=> b.address_id
    AND a.search_filter <=> b.search_filter
    AND a.card_type <=> b.card_type
    AND a.layout_type <=> b.layout_type
    AND a.item_id <=> b.item_id
    AND a.shop_id <=> b.shop_id
    AND a.local_hour <=> b.local_hour
LEFT JOIN
    dws_avg_edt_${grass_region_without_quote} c
ON
    a.user_id <=> c.user_id
    AND a.device_id <=> c.device_id
    AND a.address_state = c.address_state
    AND a.search_session_id <=> c.search_session_id
    AND a.request_id <=> c.request_id
    AND a.keyword <=> c.keyword
    AND a.address_id <=> c.address_id
    AND a.search_filter <=> c.search_filter
    AND a.card_type = c.card_type
    AND a.layout_type = c.layout_type
    AND a.item_id <=> c.item_id
    AND a.shop_id <=> c.shop_id
    AND a.local_hour <=> c.local_hour;
